def get(sid,msg_id): return c.execute('select content from messages where session_id=? and id=?',(sid,msg_id)).fetchone()[0]
def rows_between(s, label1, label2):
 x=s.split(label1,1)[1].split(label2,1)[0]
 return [[int(v) for v in line.split()] for line in x.strip().splitlines()]
def matches(g,color,bg,target=0):
 pts=[(r,c) for r,row in enumerate(g) for c,v in enumerate(row) if v==color]
 r0=min(r for r,c in pts); c0=min(c for r,c in pts)
 shape={(r-r0,c-c0) for r,c in pts}
 hh=max(dr for dr,dc in shape)+1; ww=max(dc for dr,dc in shape)+1
 out=[]
 for y in range(len(g)-hh+1):
  for x in range(len(g[0])-ww+1):
