for mid,text in rows:
 m=re.search(r'Demo pair (\d+) input \((\d+)x(\d+)\):\n(.*?)Demo pair \1 output \(\d+x\d+\):\n(.*?)(?:\n\nSame instance\.|\n\nWrong attempts|\Z)',text,re.S)
