 candA=[]; candD=[]; candZero=[]; candBgWild=[]; candZeroWild=[]
 for r0 in range(h-sh+1):
  for c0 in range(w-sw+1):
   cells=[(r0+dr,c0+dc) for dr,dc in norm]
   if all(a[r][c0]==0 for r,c0 in cells): candA.append((r0,c0))
